from __future__ import annotations

from pathlib import Path

import pytest

from flext_infra import codegen, config
from tests import c, m, tm, u


class TestsFlextInfraReleasePolicyProjection:
    """Exercise generated bytes with the real detached release CLI consumer."""

    @pytest.mark.parametrize(
        "document",
        ["Infra: [author-data]\n", "Infra:\n  release: [author-data]\n"],
    )
    @staticmethod
    def test_invalid_authored_section_shapes_fail_without_overwriting(
        tmp_path: Path,
        document: str,
    ) -> None:
        """Refuse malformed declared sections rather than replacing authored data."""
        destination = tmp_path / "config" / "infra.yaml"
        destination.parent.mkdir()
        destination.write_text(document, encoding="utf-8")
        result = codegen.FlextInfraCodegenConform.Generate.compose_project_artifact(
            tmp_path,
            destination="config/infra.yaml",
            rendered="Infra:\n  release: {}\n",
        )
        tm.fail(result)
        tm.that(result.error, has="must be a mapping")
        tm.that(destination.read_text(encoding="utf-8"), eq=document)

    @pytest.mark.parametrize("line", [None, (7, 4)])
    @staticmethod
    def test_attached_policy_survives_a_detached_standalone_clone(
        tmp_path: Path,
        line: tuple[int, int] | None,
    ) -> None:
        """The same staged member artifact works without its containing workspace."""
        if line is None:
            selected = tm.ok(
                u.Infra.load_config_document_inputs(
                    Path(__file__).resolve().parents[4],
                    filename="infra.yaml",
                ),
            )
            policy = tm.ok(
                u.validate_value(
                    m.Infra.ReleasePolicySpec,
                    u.Cli.json_walk_path(selected.values, ("Infra", "release")),
                ),
            )
            line = tm.not_none(policy.maintenance_line)
        version = f"{line[0]}.{line[1]}.6"
        owner = u.Tests.create_release_workspace(tmp_path / "owner", version=version)
        tm.ok(
            u.Cli.yaml_dump(
                owner / "config" / "infra.yaml",
                {
                    "Infra": {
                        "release": {
                            "maintenance_line": list(line),
                            "finalize_maintenance": True,
                            "publish_url": "https://owner.invalid/private-upload",
                        },
                    },
                },
            ),
        )
        tm.ok(
            u.Cli.yaml_dump(
                owner / "config" / "infra.local.yaml",
                {"Infra": {"release": {"maintenance_line": [91, 2]}}},
            ),
        )
        seed = tmp_path / "seed"
        u.Tests.WorktreeFixture.self_named_project(seed, "fixture-project")
        tm.ok(
            u.Cli.run_checked(
                [c.Infra.GIT, "branch", "-m", u.Tests.integration_branch(owner)],
                cwd=seed,
            ),
        )
        tm.ok(u.Infra.replace_project_version(seed, version))
        u.Tests.commit_git_changes(
            seed,
            c.Infra.RELEASE_COMMIT_SUBJECT.format(version=version),
        )
        member = seed.rename(owner / "member")
        u.Tests.WorktreeFixture.attach_submodule(
            owner,
            member,
            distribution="fixture-project",
            relative_path="member",
        )
        tm.ok(
            u.Cli.run_checked(
                [c.Infra.GIT, "submodule", "absorbgitdirs"],
                cwd=owner,
            ),
        )
        destination = member / "config" / "infra.yaml"
        destination.write_text(
            "# Authored consumer settings\nInfra:\n  release:\n"
            "    publish_index: true # keep this comment\n",
            encoding="utf-8",
        )
        staged = tm.not_none(
            u.Tests.planned_text(
                u.Tests.governed_project_plan(member),
                "config/infra.yaml",
            ),
        )
        tm.that(staged, has="# Authored consumer settings")
        tm.that(staged, has="# keep this comment")
        tm.fail("owner.invalid" in staged)
        destination.write_text(staged, encoding="utf-8")
        tm.that(
            tm.not_none(
                u.Tests.planned_text(
                    u.Tests.governed_project_plan(member),
                    "config/infra.yaml",
                ),
            ),
            eq=staged,
        )
        u.Tests.commit_git_changes(member, "chore: retain generated closure policy")
        standalone = tmp_path / "standalone"
        tm.ok(
            u.Cli.run_checked(
                [c.Infra.GIT, "clone", "--no-hardlinks", str(member), str(standalone)],
                cwd=tmp_path,
            ),
        )
        tm.ok(u.Cli.run_checked([c.Infra.GIT, "checkout", "--detach"], cwd=standalone))
        tm.fail((standalone / ".gitmodules").exists())
        tm.that((standalone / "config" / "infra.yaml").read_text(), eq=staged)
        u.Tests.checkout_integration(standalone)
        tm.ok(u.Cli.run_checked([c.Infra.GIT, "tag", f"v{version}"], cwd=standalone))
        u.Tests.merge_pull_request(standalone, "feat!: opaque historical feature")
        tm.ok(u.Cli.run_checked([c.Infra.GIT, "checkout", "--detach"], cwd=standalone))
        tm.that(u.Tests.run_release_main(standalone, "--phase", "plan"), eq=0)
        report = standalone / ".reports" / "release" / c.Infra.RELEASE_PLAN_FILENAME
        plan = m.Infra.ReleasePlan.model_validate_json(
            report.read_text(encoding="utf-8"),
        )
        tm.that(plan.next, eq=f"{line[0]}.{line[1]}.7")
        tm.that(str(plan.bump), eq="patch")

    @staticmethod
    def test_unconfigured_external_consumer_retains_generic_semantics(
        tmp_path: Path,
    ) -> None:
        """No containing workspace means no accidental FLEXT maintenance policy."""
        root = tmp_path / "external"
        u.Tests.WorktreeFixture.self_named_project(root, "fixture-project")
        tm.ok(
            u.Cli.run_checked(
                [
                    c.Infra.GIT,
                    "branch",
                    "-m",
                    config.Infra.codegen.branch_policy.integration_branch,
                ],
                cwd=root,
            ),
        )
        staged = tm.not_none(
            u.Tests.planned_text(
                u.Tests.governed_project_plan(root),
                "config/infra.yaml",
            ),
        )
        (root / "config" / "infra.yaml").write_text(staged, encoding="utf-8")
        effective = tm.ok(
            u.Infra.load_config_document_inputs(root, filename="infra.yaml"),
        )
        policy = tm.ok(
            u.validate_value(
                m.Infra.ReleasePolicySpec,
                u.Cli.json_walk_path(effective.values, ("Infra", "release")),
            ),
        )
        tm.that(policy.maintenance_line, eq=None)
        tm.that(policy.finalize_maintenance, eq=False)
        u.Tests.commit_git_changes(
            root, "chore: retain generated generic release policy"
        )
        version = tm.ok(u.Infra.current_workspace_version(root))
        tm.ok(u.Cli.run_checked([c.Infra.GIT, "tag", f"v{version}"], cwd=root))
        u.Tests.merge_pull_request(root, "feat: independent consumer capability")
        tm.that(u.Tests.run_release_main(root, "--phase", "plan"), eq=0)
        report = root / ".reports" / "release" / c.Infra.RELEASE_PLAN_FILENAME
        plan = m.Infra.ReleasePlan.model_validate_json(
            report.read_text(encoding="utf-8"),
        )
        tm.that(str(plan.bump), eq="minor")
